ee:message.ee:set-payload:
%dw 2.0
output application/xml
ns ns0 http://www.etb.com.co/NPlay/framework/BusAnyMessage/v1.0
ns ns1 http://www.etb.com.co/NPlay/commons/Header/v1.0
ns ns2 http://www.etb.com.co/LTE/commons/WSRequestHeader/v1.0
---
{
  ns0#"BusAnyMessage": {
    ns1#"Header": {
      ns1#"ID": payload.updateSLFServicesStatusRequest.'input'.updateSLFServicesStatusInput.wsRequestHeader2.system.correlationID default "",
      ns1#"Operation": "UpdateSLFServicesStatus",
      ns1#"RequestSystem": "MDM.Collections.Interface",
      ns1#"Version": "1",
      ns1#"Type": "IN",
      ns1#"ReqType": "SYNC",
      ns1#"RequestDateTime": now(),
      ns1#"ResponseDateTime": now()
    },
    ns0#"Body": {
      ns1#"WSInputUpdateServiceStatus_SF": {
        ns2#"WSRequestHeader": {
          ns2#"System": payload.updateSLFServicesStatusRequest."input".updateSLFServicesStatusInput.wsRequestHeader2.system.name
        },
        ns2#"RequestActualizacionEstadosOrdenes": {
          ns2#"Ordenes": payload.updateSLFServicesStatusRequest."input".updateSLFServicesStatusInput.updates.update map (item, index) -> {
            ns2#"NumeroDeConexion": item.customer.service.connectionNumber,
            ns2#"NumeroDeDocumento": item.customer.id,
            ns2#"TipoDeDocumento": item.customer.idType,
            ns2#"Tramite": item.order.subtype
          }
        }
      }
    }
  }
  }

%dw 2.0
output application/xml
ns soap http://schemas.xmlsoap.org/soap/envelope/
ns ns0 http://soap.sforce.com/schemas/class/LTE_ServiciosSuspenda_ws
---
{
  soap#"Envelope": {
    soap#"Header": {
      "SessionHeader": {
        "sessionId": payload.Envelope.Body.loginResponse.result.sessionId
      }
    },
    soap#"Body": {
      ns0#"actualizacionEstadosOrdenes": {
        ns0#"co": {
          ns0#"numeroDeConexion": vars.initialPayload.updateSLFServicesStatusRequest."input".updateSLFServicesStatusInput.updates.update.customer.service.connectionNumber,
          ns0#"numeroDocumento": vars.initialPayload.updateSLFServicesStatusRequest."input".updateSLFServicesStatusInput.updates.update.customer.id,
          ns0#"tipoDocumento": vars.initialPayload.updateSLFServicesStatusRequest."input".updateSLFServicesStatusInput.updates.update.customer.idType,
          ns0#"tramite": vars.initialPayload.updateSLFServicesStatusRequest."input".updateSLFServicesStatusInput.updates.update.order.subtype
        }
      }
    }
  }
}

%dw 2.0
output application/json
---
{
  "UpdateSLFServicesStatusOutput": {
    "WSResponseHeader2": {
      "System": {
        "name": vars.initialPayload.updateSLFServicesStatusRequest.'input'.updateSLFServicesStatusInput.wsRequestHeader2.system.name default "",
        "correlationID": vars.initialPayload.updateSLFServicesStatusRequest.'input'.updateSLFServicesStatusInput.wsRequestHeader2.system.correlationID default "",
        "processingServer": vars.initialPayload.updateSLFServicesStatusRequest.'input'.updateSLFServicesStatusInput.wsRequestHeader2.system.processingServer default "",
      },
      "Service": {
        "status": "PASS"
      }
    },
    "Outcomes": {
      "Outcome": {
        "Order": {
          "orderId": null
        },
        "Response": {
          "code": payload.Envelope.Body.actualizacionEstadosOrdenesResponse.result.codigo,
          "description": payload.Envelope.Body.actualizacionEstadosOrdenesResponse.result.mensajeError,
        }
      }
    },
    "Result": {
      "code": "SUCCESS",
      "description": "SUCCESS"
    }
  }
}

%dw 2.0
output application/json
---
{
  "Envelope": {
    "Body": {
      "UpdateSLFServicesStatusOutput": {
        "WSResponseHeader2": {
          "System": {
			"name": vars.initialPayload.updateSLFServicesStatusRequest.'input'.updateSLFServicesStatusInput.wsRequestHeader2.system.name default "",
        	"correlationID": vars.initialPayload.updateSLFServicesStatusRequest.'input'.updateSLFServicesStatusInput.wsRequestHeader2.system.correlationID default "",
        	"processingServer": vars.initialPayload.updateSLFServicesStatusRequest.'input'.updateSLFServicesStatusInput.wsRequestHeader2.system.processingServer default ""
          },
          "Service": {
            "status": "FAIL",
            "responseDate": now(),
            "statusDetail": {
              "errorCode": "NOK",
              "errorMessage": ""
            }
          }
        }
      }
    }
  }
}
